    c.progress_track = px(0x40434AFF); // ProgressBar.trackColor
    c.counter = px(0x73767CFF); // Counter.background
    c.counter_text = px(0x000000FF); // Counter.foreground
    c.tag = px(0x26282CFF); // Tag.background
    c.error = px(0xF57E84FF); // Label.errorForeground
    c.warning = px(0xD59637FF); // Label.warningForeground
    c.success = px(0x6DB083FF); // Label.successForeground
