    c.banner_success.background = px(0x203B2AFF); // Banner.successBackground
    c.banner_success.border = px(0x29583CFF); // Banner.successBorderColor
    c.run = px(0x4E9D6CFF); // RunWidget.runIconColor
    c.stop = px(0xC54E58FF); // RunWidget.stopBackground
    c.vcs_modified = px(0x70AEFFFF); // scheme FILESTATUS_MODIFIED
    c.vcs_added = px(0x73BD79FF); // scheme FILESTATUS_ADDED
    c.vcs_untracked = px(0xE88F89FF); // scheme FILESTATUS_UNKNOWN
